$st=$pdo->prepare('SELECT * FROM absensi WHERE sesi_id=? AND siswa_id=? LIMIT 1');$st->execute([$sesiId,$siswaId]);$current=$st->fetch();$selected=(string)($current['status']??'');$reason=(string)($current['keterangan']??'');$errors=[];$success='';
