 if(!$errors){try{$pdo->beginTransaction();$st=$pdo->prepare('SELECT * FROM absensi WHERE sesi_id=? AND siswa_id=? FOR UPDATE');$st->execute([$sesiId,$siswaId]);$ex=$st->fetch();
   if($ex){$old=$ex['status'];$finalStatus=$sesi['status']==='ditutup'?'dikoreksi':'valid';$source=$sesi['status']==='ditutup'?'KOREKSI':'VERIFIKASI';$up=$pdo->prepare("UPDATE absensi SET status=?,sumber_terakhir=?,status_verifikasi=?,diverifikasi_oleh=?,diverifikasi_at=NOW(),keterangan=? WHERE id=?");$up->execute([$selected,$source,$finalStatus,user_id(),$note,$ex['id']]);if($old!==$selected){$ch=$pdo->prepare('INSERT INTO absensi_perubahan (absensi_id,status_lama,status_baru,alasan,diubah_oleh) VALUES (?,?,?,?,?)');$ch->execute([$ex['id'],$old,$selected,$auditReason,user_id()]);}$id=(int)$ex['id'];}
   else{$finalStatus=$sesi['status']==='ditutup'?'dikoreksi':'valid';$source=$sesi['status']==='ditutup'?'KOREKSI':'VERIFIKASI';$ins=$pdo->prepare("INSERT INTO absensi (sesi_id,siswa_id,status,waktu_scan,scan_oleh,metode_awal,sumber_terakhir,status_verifikasi,diverifikasi_oleh,diverifikasi_at,keterangan) VALUES (?,?,?,NULL,?,?,?, ?,?,NOW(),?)");$ins->execute([$sesiId,$siswaId,$selected,user_id(),'MANUAL',$source,$finalStatus,user_id(),$note]);$id=(int)$pdo->lastInsertId();$ch=$pdo->prepare('INSERT INTO absensi_perubahan (absensi_id,status_lama,status_baru,alasan,diubah_oleh) VALUES (?,?,?,?,?)');$ch->execute([$id,null,$selected,$auditReason,user_id()]);}
   $pdo->commit();absensi_audit($pdo,$sesi['status']==='ditutup'?'KOREKSI_STATUS':'MANUAL_STATUS',$id,($sesi['status']==='ditutup'?'Koreksi setelah kunci. ':'').'Status '.$siswa['nama'].' = '.$selected.'. Alasan: '.$auditReason);$success='Status berhasil disimpan.';$st=$pdo->prepare('SELECT * FROM absensi WHERE sesi_id=? AND siswa_id=? LIMIT 1');$st->execute([$sesiId,$siswaId]);$current=$st->fetch();
