'?>>Sakit</option><option value="A" <?=$selected==='A'?'selected':''?>>Alpa</option></select></label><label>Alasan/Keterangan <span id="reasonRequiredMark" style="color:#dc2626;display:none">*</span><input type="hidden" name="alasan" id="reasonField" value="<?=e($reason)?>"><div id="reasonSummary" class="reason-summary">Pilih status Izin atau Sakit untuk menentukan alasan. Hadir, Alpa, dan Terlambat tidak wajib keterangan.</div></label></div><div id="manualReasonBox" class="manual-reason-box" hidden><div class="manual-reason-title">Pilih alasan</div><select id="manualReasonSelect" class="form-control"><option value="">- Pilih alasan -</option></select><div id="manualReasonOptions" class="reason-options" style="margin-top:10px"></div><label id="manualExtraWrap" class="reason-extra" hidden>Keterangan tambahan <span id="manualExtraMark" style="color:#dc2626;display:none">*</span><textarea id="manualExtra" class="form-control" rows="3" maxlength="500" placeholder="Tulis keterangan tambahan..."></textarea><small id="manualExtraHelp">Opsional.</small></label></div><div class="form-actions"><button class="btn btn-primary">Simpan <?= $mode==='koreksi'?'Koreksi':'Status'?></button><a class="btn btn-secondary" href="<?=BASE_URL?>absensi/daftar.php?sesi_id=<?=$sesiId?>">Batal</a></div></form></div></section></main><script>document.addEventListener('DOMContentLoaded',function(){(function(){const s=document.getElementById('manualStatus'),f=document.getElementById('reasonField'),m=document.getElementById('reasonRequiredMark'),box=document.getElementById('manualReasonBox'),opts=document.getElementById('manualReasonOptions'),extra=document.getElementById('manualExtraWrap'),extraInput=document.getElementById('manualExtra'),extraMark=document.getElementById('manualExtraMark'),summary=document.getElementById('reasonSummary');const choices={I:['Dijemput orang tua/wali','Keperluan keluarga','Keperluan pribadi','Keperluan sekolah','Kondisi kesehatan','Lainnya'],S:['Kurang enak badan','Demam','Berobat','Kondisi kesehatan lainnya','Lainnya']};let selected='';function sync(){const st=s.value;if(st!=='I'&&st!=='S'){m.style.display='none';box.hidden=true;extra.hidden=true;summary.textContent='Untuk Hadir, Alpa, atau Terlambat, keterangan boleh dikosongkan.';return}m.style.display='inline';box.hidden=false;summary.textContent=st==='S'?'Pilih kondisi sakit.':'Pilih alasan izin.';opts.innerHTML='';const sel=document.getElementById('manualReasonSelect');sel.innerHTML='<option value="">- Pilih alasan -</option>';selected='';extraInput.value='';extra.hidden=true;(choices[st]||[]).forEach(v=>{sel.insertAdjacentHTML('beforeend','<option value="'+v.replace(/"/g,'&quot;')+'">'+v+'</option>');const b=document.createElement('button');b.type='button';b.className='reason-option';b.textContent=v;b.addEventListener('click',()=>{selected=v;opts.querySelectorAll('.reason-option').forEach(x=>x.classList.remove('active'));b.classList.add('active');extra.hidden=false;const other=v==='Lainnya';extraMark.style.display=other?'inline':'none';document.getElementById('manualExtraHelp').textContent=other?'Wajib diisi jika memilih Lainnya.':'Opsional. Isi jika perlu penjelasan tambahan.';extraInput.placeholder=other?'Wajib: jelaskan alasan...':'Tambahkan keterangan jika diperlukan...';f.value=v;summary.textContent='Dipilih: '+v});opts.appendChild(b)});sel.onchange=function(){const v=sel.value;if(!v)return;selected=v;opts.querySelectorAll('.reason-option').forEach(x=>x.classList.toggle('active',x.textContent===v));extra.hidden=false;const other=v==='Lainnya';extraMark.style.display=other?'inline':'none';document.getElementById('manualExtraHelp').textContent=other?'Wajib diisi jika memilih Lainnya.':'Opsional. Isi jika perlu penjelasan tambahan.';extraInput.placeholder=other?'Wajib: jelaskan alasan...':'Tambahkan keterangan jika diperlukan...';f.value=v;summary.textContent='Dipilih: '+v};}document.querySelector('form').addEventListener('submit',e=>{if(s.value==='I'||s.value==='S'){if(!selected){e.preventDefault();return}const v=extraInput.value.trim();if(selected==='Lainnya'&&!v){e.preventDefault();extraInput.focus();return}f.value=selected+(v?' — '+v:'')}});s.addEventListener('change',sync);sync()})();});</script><style>.reason-summary{margin-top:7px;padding:10px 12px;background:#f8fafc;border:1px solid #e2e8f0;border-radius:10px;color:#475569}.manual-reason-box{margin-top:16px;padding:16px;border:1px solid #e2e8f0;border-radius:12px;background:#f8fafc}.manual-reason-box[hidden]{display:none}.manual-reason-title{font-weight:700;margin-bottom:10px}</style><?php require_once __DIR__.'/../layouts/footer.php';?>
